"""The Adaptive Trader's Notes: brand layer for Streamlit dashboards (tokens from the ATN design system, dark theme)."""
import plotly.graph_objects as go
import plotly.io as pio

T = dict(ground='#0a0a0a', surface='#121212', raised='#1a1918', grid='#171615', line='#2a2724', line_strong='#6e675f',
         ink='#f3ece2', muted='#a89f95', copper='#e3b48e', copper_deep='#c58c69', copper_light='#f8d6b4',
         left='#f4a062', right='#85cac5', pivot='#f6eedd', left_soft='#2a1c13', right_soft='#132322', copper_soft='#241b15',
         c3='#e8dccb', c4='#9b958f', div_neg1='#74492e', div0='#2b2927', div_pos1='#3d5d5a')
DISPLAY = "Barlow, 'Helvetica Neue', Arial, sans-serif"
MONO = "'IBM Plex Mono', ui-monospace, Menlo, Consolas, monospace"

pio.templates['atn'] = go.layout.Template(layout=dict(
    font=dict(family=DISPLAY, color=T['ink'], size=12),
    colorway=[T['left'], T['right'], T['c3'], T['c4']],
    paper_bgcolor=T['surface'], plot_bgcolor=T['surface'],
    xaxis=dict(gridcolor=T['line'], linecolor=T['line_strong'], zerolinecolor=T['line_strong'], tickfont=dict(family=MONO, color=T['muted'], size=11)),
    yaxis=dict(gridcolor=T['line'], linecolor=T['line_strong'], zerolinecolor=T['line_strong'], tickfont=dict(family=MONO, color=T['muted'], size=11)),
    legend=dict(font=dict(family=DISPLAY, color=T['muted'])),
    hoverlabel=dict(bgcolor=T['raised'], bordercolor=T['line_strong'], font=dict(family=MONO, color=T['ink']))))

FONTS = """@font-face{font-family:'Barlow';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:swap;}@font-face{font-family:'Barlow';src:url(data:font/woff2;base64,) format('woff2');font-weight:500;font-style:normal;font-display:swap;}@font-face{font-family:'Barlow';src:url(data:font/woff2;base64,) format('woff2');font-weight:600;font-style:normal;font-display:swap;}@font-face{font-family:'IBM Plex Mono';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:swap;}@font-face{font-family:'IBM Plex Mono';src:url(data:font/woff2;base64,) format('woff2');font-weight:500;font-style:normal;font-display:swap;}"""

CSS = FONTS + """
.stApp {background:#0a0a0a; color:#f3ece2;}
.stApp, .stApp p, .stApp li, .stApp label, .stApp h1, .stApp h2, .stApp h3, .stApp h4, .stApp h5, .stApp input, .stApp button, .stApp textarea,
.stApp [data-testid="stMarkdownContainer"], .stApp [data-testid="stCaptionContainer"] {font-family: Barlow, 'Helvetica Neue', Arial, sans-serif !important;}
.stApp h1, .stApp h2, .stApp h3 {font-weight:600 !important; letter-spacing:-0.005em;}
[data-testid="stSidebar"] {background:#121212 !important; border-right:1px solid #2a2724;}
[data-testid="stHeader"] {background:#0a0a0a !important;}
.stApp code {font-family:'IBM Plex Mono', monospace !important; background:#1a1918; color:#e3b48e;}
.atn-kicker {font-family:Barlow, sans-serif; font-weight:500; font-size:13px; line-height:16px; letter-spacing:0.2em; text-transform:uppercase; color:#e3b48e; margin:0 0 4px 0;}
.atn-kicker b {color:#a89f95; font-weight:500;}
[data-testid="stExpander"] details {border:1px solid #2a2724 !important; border-radius:4px !important; background:#121212;}
[data-baseweb="tab-list"] button[aria-selected="true"] {color:#e3b48e !important;}
[data-baseweb="tab-highlight"] {background:#e3b48e !important;}
:focus-visible {outline:2px solid #f8d6b4 !important; outline-offset:2px;}
"""


def inject(st, product=None):
    st.markdown('<style>' + CSS + '</style>', unsafe_allow_html=True)
    if product:
        st.markdown(f"<div class='atn-kicker'>The Adaptive Trader's Notes <b>&middot; {product}</b></div>", unsafe_allow_html=True)
